<div class="va-shop-page"><div class="va-static-hero"><div><span>Compare products</span><h1>Compare</h1></div><nav><a href="<?= base_url() ?>">Home</a> / Compare</nav></div><?php if(empty($shop_items)): ?><div class="va-shop-empty"><i class="bi bi-shuffle"></i><h2>No products selected for comparison</h2><a class="btn va-why-button" href="<?= base_url('accessories') ?>">Browse Products</a></div><?php else: ?><div class="va-compare-table"><div class="va-compare-row va-compare-products"><b>Product</b><?php foreach($shop_items as $item): ?><article><button class="shop-action va-remove" data-action="remove-compare" data-product-id="<?= $item->id ?>">×</button><?php if($item->primary_image): ?><img src="<?= $item->primary_image ?>" alt=""><?php endif; ?><h2><?= html_escape($item->name) ?></h2></article><?php endforeach; ?></div><div class="va-compare-row"><b>Price</b><?php foreach($shop_items as $item): ?><span>&#8377; <?= number_format($item->price) ?></span><?php endforeach; ?></div><div class="va-compare-row"><b>Availability</b><?php foreach($shop_items as $item): ?><span>In stock</span><?php endforeach; ?></div><div class="va-compare-row"><b>Action</b><?php foreach($shop_items as $item): ?><span><button class="btn va-why-button shop-action" data-action="cart" data-product-id="<?= $item->id ?>">Add to Cart</button></span><?php endforeach; ?></div></div><?php endif; ?></div>
